// The licence window: everything this application ships under, in one place.
//
// The order is the point. MeshBench's own licence first, then the modified
// forks - they are our changes to other people's work, so they lead - then
// what is bundled, then every Go module actually linked, then what is only
// downloaded at runtime, then the map data attributions. The content is
// generated by tools/licgen and embedded, so the window cannot drift from
// what the binary was built with.
package workbench

import (
	"strings"

	"gioui.org/layout"
	"gioui.org/widget"

	"github.com/MeshBench/meshbench/internal/gui/comp"
	"github.com/MeshBench/meshbench/internal/gui/state"
	"github.com/MeshBench/meshbench/internal/gui/theme"
	"github.com/MeshBench/meshbench/internal/workbench/licences"
)

type licPanel struct {
	built  bool
	file   licences.File
	err    string
	search comp.Field
	all    comp.Chip
	chips  []comp.Chip
	filter string
	list   widget.List
	// open holds the full-text toggles, pooled by entry so identity
	// survives filtering; the licence text only exists on screen when
	// somebody asked for it.
	open   map[string]*widget.Clickable
	opened map[string]bool
	// openAt is the section a capture asked for, applied on the first frame.
	openAt string
}

func (p *licPanel) build() {
	p.built = true
	p.filter = p.openAt
	p.search.Hint = "search licences"
	p.search.Editor.SingleLine = true
	p.list.Axis = layout.Vertical
	p.open = map[string]*widget.Clickable{}
	p.opened = map[string]bool{}
	f, err := licences.Load()
	if err != nil {
		p.err = err.Error()
		return
	}
	p.file = f
	p.chips = make([]comp.Chip, len(f.Sections))
}

func (p *licPanel) Draw(t *theme.Theme, gtx layout.Context, s *state.Snapshot) layout.Dimensions {
	if !p.built {
		p.build()
	}
	if p.err != "" {
		return comp.Card(t, "Licences", comp.Text(t, t.Sz.Body, t.P.Bad,
			"the licence inventory did not load: "+p.err))(gtx)
	}
	if p.all.Click.Clicked(gtx) {
		p.filter = ""
	}
	for i := range p.chips {
		if p.chips[i].Click.Clicked(gtx) {
			p.filter = p.file.Sections[i].Key
		}
	}
	return layout.Flex{Axis: layout.Vertical}.Layout(gtx,
		layout.Rigid(func(gtx layout.Context) layout.Dimensions {
			return layout.Inset{Bottom: t.Sp.S}.Layout(gtx, p.header(t))
		}),
		layout.Rigid(func(gtx layout.Context) layout.Dimensions {
			return layout.Inset{Bottom: t.Sp.S}.Layout(gtx,
				func(gtx layout.Context) layout.Dimensions {
					return p.chipRow(t, gtx)
				})
		}),
		layout.Rigid(func(gtx layout.Context) layout.Dimensions {
			return layout.Inset{Bottom: t.Sp.S}.Layout(gtx,
				func(gtx layout.Context) layout.Dimensions {
					return p.search.Layout(t, gtx)
				})
		}),
		layout.Flexed(1, func(gtx layout.Context) layout.Dimensions {
			return p.body(t, gtx)
		}),
	)
}

// header is the project's own entry: name, version, and the licence line,
// which is a warning for as long as ADR-0001 is unresolved.
func (p *licPanel) header(t *theme.Theme) layout.Widget {
	proj := licences.Entry{Name: "MeshBench", Licence: "unknown"}
	for _, s := range p.file.Sections {
		if s.Key == "project" && len(s.Entries) > 0 {
			proj = s.Entries[0]
		}
	}
	licInk := t.P.Good
	if strings.Contains(strings.ToLower(proj.Licence), "none") {
		licInk = t.P.Warn
	}
	return comp.Card(t, "", func(gtx layout.Context) layout.Dimensions {
		return layout.Flex{Axis: layout.Vertical}.Layout(gtx,
			layout.Rigid(comp.Text(t, t.Sz.Title, t.P.Ink, "MeshBench "+Version)),
			layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Inset{Top: t.Sp.XS}.Layout(gtx,
					comp.Text(t, t.Sz.Body, licInk, "licence: "+proj.Licence))
			}),
			layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Inset{Top: t.Sp.XS}.Layout(gtx,
					comp.Text(t, t.Sz.Caption, t.P.Dim, proj.Detail))
			}),
		)
	})
}

func (p *licPanel) chipRow(t *theme.Theme, gtx layout.Context) layout.Dimensions {
	total := 0
	kids := []layout.FlexChild{}
	for i := range p.file.Sections {
		if p.file.Sections[i].Key == "project" {
			continue
		}
		i := i
		s := &p.file.Sections[i]
		total += len(s.Entries)
		kids = append(kids, layout.Rigid(func(gtx layout.Context) layout.Dimensions {
			return layout.Inset{Left: t.Sp.XS}.Layout(gtx,
				func(gtx layout.Context) layout.Dimensions {
					return p.chips[i].Layout(t, gtx, s.Title,
						itoa(len(s.Entries)), p.filter == s.Key,
						t.P.Accent)
				})
		}))
	}
	all := layout.Rigid(func(gtx layout.Context) layout.Dimensions {
		return p.all.Layout(t, gtx, "All", itoa(total), p.filter == "", t.P.Accent)
	})
	return layout.Flex{Alignment: layout.Middle}.Layout(gtx,
		append([]layout.FlexChild{all}, kids...)...)
}

// shownEntry is one row of the flattened, filtered list.
type shownEntry struct {
	section *licences.Section
	entry   *licences.Entry
	heading bool
}

func (p *licPanel) shown() []shownEntry {
	want := strings.ToLower(fieldText(&p.search))
	var rows []shownEntry
	for i := range p.file.Sections {
		s := &p.file.Sections[i]
		if s.Key == "project" {
			continue
		}
		if p.filter != "" && s.Key != p.filter {
			continue
		}
		var here []shownEntry
		for j := range s.Entries {
			e := &s.Entries[j]
			if want != "" && !strings.Contains(strings.ToLower(e.Name), want) &&
				!strings.Contains(strings.ToLower(e.Licence), want) &&
				!strings.Contains(strings.ToLower(e.Detail), want) {
				continue
			}
			here = append(here, shownEntry{section: s, entry: e})
		}
		if len(here) > 0 {
			rows = append(rows, shownEntry{section: s, heading: true})
			rows = append(rows, here...)
		}
	}
	return rows
}

func (p *licPanel) body(t *theme.Theme, gtx layout.Context) layout.Dimensions {
	rows := p.shown()
	if len(rows) == 0 {
		return layout.Center.Layout(gtx,
			comp.Text(t, t.Sz.Body, t.P.Dim, "nothing matches the search"))
	}
	return p.list.Layout(gtx, len(rows), func(gtx layout.Context, i int) layout.Dimensions {
		r := rows[i]
		if r.heading {
			return layout.Inset{Top: t.Sp.S, Bottom: t.Sp.XS}.Layout(gtx,
				func(gtx layout.Context) layout.Dimensions {
					return layout.Flex{Axis: layout.Vertical}.Layout(gtx,
						layout.Rigid(comp.SectionTitle(t, r.section.Title)),
						layout.Rigid(comp.Text(t, t.Sz.Caption, t.P.Faint, r.section.Blurb)),
					)
				})
		}
		return layout.Inset{Bottom: t.Sp.XS}.Layout(gtx,
			func(gtx layout.Context) layout.Dimensions {
				return p.entryCard(t, gtx, r)
			})
	})
}

func (p *licPanel) entryCard(t *theme.Theme, gtx layout.Context, r shownEntry) layout.Dimensions {
	key := r.section.Key + "/" + r.entry.Name
	tog, ok := p.open[key]
	if !ok {
		tog = &widget.Clickable{}
		p.open[key] = tog
	}
	if tog.Clicked(gtx) {
		p.opened[key] = !p.opened[key]
	}
	e := r.entry
	return comp.Card(t, "", func(gtx layout.Context) layout.Dimensions {
		kids := []layout.FlexChild{
			layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Flex{Alignment: layout.Baseline}.Layout(gtx,
					layout.Rigid(comp.Text(t, t.Sz.Body, t.P.Ink, e.Name)),
					layout.Rigid(func(gtx layout.Context) layout.Dimensions {
						return layout.Inset{Left: t.Sp.S}.Layout(gtx,
							comp.Mono(t, t.Sz.Caption, t.P.Dim, e.Licence))
					}),
				)
			}),
		}
		if e.Detail != "" {
			kids = append(kids, layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Inset{Top: t.Sp.XS}.Layout(gtx,
					comp.Text(t, t.Sz.Caption, t.P.Dim, e.Detail))
			}))
		}
		if e.Link != "" {
			kids = append(kids, layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Inset{Top: t.Sp.XS}.Layout(gtx,
					comp.Mono(t, t.Sz.Caption, t.P.Faint, e.Link))
			}))
		}
		if e.Text != "" {
			label := "show the licence text"
			if p.opened[key] {
				label = "hide the licence text"
			}
			kids = append(kids, layout.Rigid(func(gtx layout.Context) layout.Dimensions {
				return layout.Inset{Top: t.Sp.XS}.Layout(gtx,
					func(gtx layout.Context) layout.Dimensions {
						return tog.Layout(gtx,
							comp.Text(t, t.Sz.Caption, t.P.Accent, label))
					})
			}))
			if p.opened[key] {
				kids = append(kids, layout.Rigid(func(gtx layout.Context) layout.Dimensions {
					return layout.Inset{Top: t.Sp.S}.Layout(gtx,
						comp.Mono(t, t.Sz.Caption, t.P.Dim, e.Text))
				}))
			}
		}
		return layout.Flex{Axis: layout.Vertical}.Layout(gtx, kids...)
	})(gtx)
}
